class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def removeElements(self, head, val):
        dummy = ListNode()
        tail = dummy
        cur = head
        while cur:
            if cur.val != val:
                tail.next = ListNode(cur.val)
                tail = tail.next
            cur = cur.next
        return dummy.next

